void ObjExtend ( struct worker * wrk , struct objcore * oc , ssize_t l , int final ) { const struct obj_methods * om = obj_getmethods ( oc ) ; CHECK_OBJ_NOTNULL ( wrk , WORKER_MAGIC ) ; CHECK_OBJ_NOTNULL ( oc -> boc , BOC_MAGIC ) ; AN ( om -> objextend ) ; assert ( l >= 0 ) ; Lck_Lock ( & oc -> boc -> mtx ) ; if ( l > 0 ) { obj_extend_condwait ( oc ) ; om -> objextend ( wrk , oc , l ) ; oc -> boc -> fetched_so_far += l ; AZ ( pthread_cond_broadcast ( & oc -> boc -> cond ) ) ; } Lck_Unlock ( & oc -> boc -> mtx ) ; assert ( oc -> boc == NULL || oc -> boc -> state < BOS_FINISHED ) ; } 